using System;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Diagnostics;
class FootballPetTests {
 static int failures,checks;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}static void Check(string n,bool v){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}
 static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static void Capture(Window pet,FootballWorld ball,string path){var sprite=(SpriteView)Get(pet,"sprite");double scale=(double)Get(pet,"scale");double pad=(pet.Width-192*scale)/2;var visual=new DrawingVisual();RenderOptions.SetBitmapScalingMode(visual,BitmapScalingMode.NearestNeighbor);using(var dc=visual.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(18,38,53)),null,new Rect(0,0,720,420));dc.PushTransform(new TranslateTransform(200,70));typeof(SpriteView).GetMethod("OnRender",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(sprite,new object[]{dc});dc.Pop();var window=(FootballWindow)Get(pet,"footballWindow");if(window!=null&&ball.Active){var image=(SpriteView)window.Content;dc.DrawImage(image.Frame,new Rect(200+ball.X-pet.Left-pad-ball.Radius,70+ball.Y-pet.Top-90-ball.Radius,ball.Radius*2,ball.Radius*2));}}var bitmap=new RenderTargetBitmap(720,420,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
 static void CaptureWorld(Window pet,FootballWorld ball,Rect area,string path){double zoom=.75;var visual=new DrawingVisual();RenderOptions.SetBitmapScalingMode(visual,BitmapScalingMode.NearestNeighbor);using(var dc=visual.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(18,38,53)),null,new Rect(0,0,960,450));dc.PushTransform(new ScaleTransform(zoom,zoom));double ox=area.Right-1280,oy=area.Bottom-600;dc.DrawLine(new Pen(Brushes.SlateGray,2),new Point(1278,0),new Point(1278,600));dc.DrawLine(new Pen(Brushes.SlateGray,2),new Point(0,598),new Point(1280,598));double scale=(double)Get(pet,"scale"),pad=(pet.Width-192*scale)/2;dc.PushTransform(new TranslateTransform(pet.Left+pad-ox,pet.Top+90-oy));typeof(SpriteView).GetMethod("OnRender",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(Get(pet,"sprite"),new object[]{dc});dc.Pop();var window=(FootballWindow)Get(pet,"footballWindow");dc.DrawImage(((SpriteView)window.Content).Frame,new Rect(ball.X-ox-ball.Radius,ball.Y-oy-ball.Radius,ball.Radius*2,ball.Radius*2));dc.Pop();}var bitmap=new RenderTargetBitmap(960,450,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();((BubbleQueue)Get(pet,"messages")).Clear();((VoiceRuntime)Get(pet,"voices")).Settings.Volume=.01;var sprites=(SpriteActions)Get(pet,"signature");Check("football actor strips loaded",sprites.Has("juggle")&&sprites.Has("kick-play"));Call(pet,"StartFootball","throw");var ball=(FootballWorld)Get(pet,"football");var window=(FootballWindow)Get(pet,"footballWindow");Check("throw opens independently interactive ball",ball.Active&&window.IsVisible);double now=((Stopwatch)Get(pet,"clock")).Elapsed.TotalSeconds,scale=(double)Get(pet,"scale"),pad=(pet.Width-192*scale)/2;
  Check("toss begins with upward flick",(string)Get(pet,"footballMode")=="flick");Call(pet,"StartFootball","volley");double start=(double)Get(pet,"footballKickStart");for(int i=0;i<106;i++)Call(pet,"TickFootball",start+i/120.0,1.0/120);Check("incoming ball remains independent before contact",!(bool)Get(pet,"footballReleased"));Call(pet,"TickFootball",start+106/120.0,1.0/120);Check("contact releases exactly one independent ball",(bool)Get(pet,"footballReleased")&&(bool)Get(pet,"footballHit")&&ball.VX>0&&ball.VY<0);var voice=(VoiceRuntime)Get(pet,"voices");for(int wait=0;wait<100&&voice.OpenedCount==0;wait++)Pump();Check("original shot voice loads without cancelling play",voice.OpenedCount>0&&ball.Active&&(voice.CurrentId=="finish1"||voice.CurrentId=="finish2"));Capture(pet,ball,Path.Combine(args[0],"v5.10-volley-contact-native.png"));for(int i=107;i<=261;i++)Call(pet,"TickFootball",start+i/120.0,1.0/120);Check("volley reaches landing then flight",(string)Get(pet,"footballMode")=="flight");
  Call(pet,"StopFootball");Rect area=(Rect)Call(pet,"WorkArea");pet.Left=area.Right-pet.Width-420;pet.Top=area.Bottom-pet.Height-15;((BubbleQueue)Get(pet,"messages")).Clear();Call(pet,"StartFootball","throw");double epoch=((Stopwatch)Get(pet,"clock")).Elapsed.TotalSeconds,startLeft=pet.Left;bool chased=false,shot=false,bounced=false;int capture=0;for(int i=0;i<900;i++){double previousVX=ball.VX;Call(pet,"TickFootball",epoch+i/60.0,1.0/60);string mode=(string)Get(pet,"footballMode");chased|=Math.Abs(pet.Left-startLeft)>10;shot|=(mode=="volley"||mode=="flight")&&(bool)Get(pet,"footballHit");bounced|=(mode=="flight"||mode=="volley"&&(bool)Get(pet,"footballReleased"))&&previousVX>0&&ball.VX<0;if(i%3==0&&capture<180){CaptureWorld(pet,ball,area,Path.Combine(args[0],"football-world-"+(capture++).ToString("D3")+".png"));}if(bounced&&mode=="chase"&&i>300)break;}Check("full toss sequence moves actor to chase",chased);Check("full toss sequence reaches actual shot",shot);Check("actual shot rebounds off screen edge",bounced);
  Call(pet,"StartFootball","juggle");double left=pet.Left,top=pet.Top;now=((Stopwatch)Get(pet,"clock")).Elapsed.TotalSeconds;double firstY=0;for(int i=0;i<32;i++){Call(pet,"TickFootball",now+i*.05,.05);if(i==0)firstY=ball.Y;Capture(pet,ball,Path.Combine(args[0],"juggle-"+i.ToString("D3")+".png"));}Check("juggling stays in place",pet.Left==left&&pet.Top==top);Check("juggling ball actually moves",Math.Abs(firstY-ball.Y)>1);Set(pet,"menuOpen",true);double x=ball.X,y=ball.Y;Call(pet,"TickFootball",now+2,.05);Check("menu pauses ball and hides overlay",!window.IsVisible&&ball.X==x&&ball.Y==y);Set(pet,"menuOpen",false);Call(pet,"TickFootball",now+2.05,.05);Check("closing menu resumes ball",window.IsVisible);
  Call(pet,"StartFootball","idle-juggle");Check("autonomous juggle has bounded duration",!Double.IsInfinity((double)Get(pet,"footballUntil")));Call(pet,"TickFootball",(double)Get(pet,"footballUntil")+.1,.01);Check("autonomous juggle returns to idle and keeps prop",ball.Active&&window.IsVisible&&(string)Get(pet,"footballMode")=="rest");
  Call(pet,"StartFootball","throw");pet.Hide();Check("hide removes football window",!ball.Active&&!window.IsVisible);pet.Show();Call(pet,"StartFootball","throw");Call(pet,"NotifyWorkEnd",new SkillAlert{Count=15,Key="work-end:test",Text="距离下班还有 15 分钟。",Row=3});Check("real reminders preempt action while retaining ball",ball.Active&&(string)Get(pet,"footballMode")=="rest");Call(pet,"StartFootball","throw");Call(pet,"StartFootball","stop");Check("stop button ends physics and overlay",!ball.Active&&!window.IsVisible);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
}
